	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Case_
	 */
		public Case_ createCase_( CreateCase_Command command ) {

		Case_ entity = new Case_();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCase_Id( command.getCase_Id() );
            entity.setCaseNumber( command.getCaseNumber() );
            entity.setSubject( command.getSubject() );
            entity.setDescription( command.getDescription() );
            entity.setSlaDue( command.getSlaDue() );
            entity.setStatus( command.getStatus() );
            entity.setPriority( command.getPriority() );
            entity.setOrigin( command.getOrigin() );
            entity.setSeverity( command.getSeverity() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Case_ {0} ", entity.toString() );

		return entity;
	}

